// Sin bot configurado no hay nada que consultar: el flujo termina aquí.
if (!$env.TELEGRAM_BOT_TOKEN || !$env.TELEGRAM_CHAT_ID) return [];
// Telegram entrega los mensajes a partir de este número; se guarda entre ejecuciones
// para no responder dos veces el mismo.
const memoria = $getWorkflowStaticData('global');
return [{ json: { offset: memoria.offset || 0 } }];

// Busca el comando /estado entre los mensajes nuevos.
const memoria = $getWorkflowStaticData('global');
const mensajes = $input.first().json.result || [];
let pedido = null;
for (const u of mensajes) {
  memoria.offset = Math.max(memoria.offset || 0, u.update_id + 1);
  const m = u.message;
  if (!m || !m.text) continue;
  // Solo se atiende al grupo de alertas: nadie más puede consultar el laboratorio.
  if (String(m.chat.id) !== String($env.TELEGRAM_CHAT_ID)) continue;
  if (/^[/]estado(@[A-Za-z0-9_]+)?( |$)/i.test(m.text.trim())) {
    pedido = { chat_id: m.chat.id, message_id: m.message_id };
  }
}
// Varios /estado seguidos se responden una sola vez.
return pedido ? [{ json: pedido }] : [];

// Arma el resumen con las cuatro respuestas de Zabbix (una por consulta, por su id).
const r = {};
for (const i of $input.all()) r[i.json.id] = i.json.result;

const items = {};
for (const i of (r[1] || [])) items[i.key_] = i;
const num = (clave) => (items[clave] && items[clave].lastvalue !== '' ? Number(items[clave].lastvalue) : null);
const seg = (v) => (v === null ? '' : ' ' + v.toFixed(1).replace('.', ',') + ' s');

const codigo = num('web.test.rspcode[App MS Motos,health]');
const tiempo = num('web.test.time[App MS Motos,health,resp]');
const app = codigo === 200
  ? `responde (HTTP 200, ${Math.round((tiempo || 0) * 1000)} ms)`
  : `NO RESPONDE (${codigo === null ? 'sin datos' : 'código ' + codigo})`;

const robot = ['consulta', 'agendar'].map((x) => {
  const s = num(`rpa.status[${x}]`);
  return `${x} ${s === 1 ? 'OK' : s === 0 ? 'FALLO' : 'sin datos'}${seg(num(`rpa.duration.total[${x}]`))}`;
}).join(' · ');

const hosts = r[2] || [];
// available: 1 responde, 2 no responde, 0 todavía sin datos.
const caidos = hosts.filter((h) => (h.interfaces || []).some((i) => String(i.available) === '2')).map((h) => h.host);

const SEVERIDAD = ['Sin clasificar', 'Información', 'Advertencia', 'Media', 'Alta', 'Desastre'];
const problemas = (r[3] || []).sort((a, b) => Number(b.severity) - Number(a.severity));

const lineas = [
  `📊 Estado del laboratorio · ${$now.toFormat('dd/MM HH:mm')}`,
  `Aplicación: ${app}`,
  `Robot: ${robot}`,
  `Equipos: ${hosts.length} monitoreados` + (caidos.length ? `, sin responder: ${caidos.join(', ')}` : ', todos responden'),
  `Recuperaciones automáticas hoy: ${Number(r[4] || 0)}`,
  problemas.length ? `Problemas abiertos: ${problemas.length}` : 'Problemas abiertos: ninguno',
];
for (const p of problemas.slice(0, 6)) lineas.push(`  • [${SEVERIDAD[Number(p.severity)]}] ${p.name}`);
if (problemas.length > 6) lineas.push(`  … y ${problemas.length - 6} más`);

const pedido = $('Filtrar comandos').first().json;
return [{ json: {
  chat_id: pedido.chat_id,
  reply_to_message_id: pedido.message_id,
  text: lineas.join(String.fromCharCode(10)),
  disable_web_page_preview: true,
} }];
